for _lead in ("lead_electrical", "lead_mechanical", "lead_software", "lead_procurement", "lead_simulation"):
    SPECS[_lead].tools["use_service"] = "Run an operation of a connected outside service listed in services. Reading runs at once; changes wait for the person."


SOP = """# Standard procedure
Every message from Headquarters is a command, in <command>. Follow these steps every time.
1. Read: check department_state for what's agreed, what failed and what's waiting, and list_deliverables for what other departments have already made. Never redo or duplicate what exists.
2. Scope: do exactly the items in the command. done_when says what finished means.
3. Sort inputs: each thing you need is yours, another department's, or the person's. Ask the person only for what only they can provide. Look in project_files first: the person may already have added it. If you need a tool or a conversion nobody has (such as getting CAD into a simulator, or a data format another program reads), use the skills you were given, and if none covers it, ask Reception with request_tool: External Service finds an established tool and guides the person through it. Don't write your own converter or improvise one with the person meanwhile; carry on with everything else.
4. Do: make the real thing with your tools. If a value is unknown, choose one and list it under provisional.
5. Check: the app's automatic checks are the only evidence. Never claim something works because you wrote it.
6. Report: return one report. Use DONE only if every item is finished. If you can't continue use BLOCKED, name the owner in needs, and put in can_give_now what you can hand over anyway with cautious assumptions: one unknown never blocks everything.

Always: pins come only from the wiring list and messages only from packet definitions, never retype them. Anything already agreed changes only through raise_change_request. If a tool or generated code is broken, report BUG and never work around it or disable code. When you're told to carry on after reporting a BUG, run the tool again before saying anything, because tools are often fixed in between. Report the BUG again only if the new attempt fails, and quote its new result. Never remove a feature the person asked for to get past a check: if a pin isn't in the wiring list, report BLOCKED with Electrical as the owner. What the person says about their own hardware and wiring is a fact, so build on it and never withhold a feature for lack of proof: record it, list any doubt under not_checked, and don't stop work for lack of a photo or document. A tool refusing your input isn't a BUG either: correct the input, or carry on without that tool. A script or program you wrote that fails inside a connected program (such as a CAD script stopping with an error) is your own code to fix: read the error, correct it and send it again; it isn't a BUG. A window or dialog that someone has to click through (such as an add-in's export dialog) isn't a missing tool: hand it to the person with hand_to_person, with the exact choices to make and what to send back. When a script's results matter, print them: some connected programs send back only what a script prints, not what it returns. A design mismatch or a decision someone has to make isn't a BUG: use BLOCKED or raise_change_request. Plan one build of what the person asked for: no prototype, test-piece or full-build stages unless they asked. Never ask the person to approve or confirm anything, because the app already shows those, and don't ask what the requests section shows they've answered. Safety locks stop motion, never messages or tests. Only a person approves gates, flashes boards and spends money. Each tool call costs money, so make the fewest that do the job."""


SKILLS = {"firmware": ["firmware"], "bench_fake": ["bench"], "bench_tests": ["bench"]}  # Agent id -> skill files in buildanything/skills.


def skill_text(agent: str) -> str:
    from pathlib import Path

    folder = Path(__file__).parent / "skills"
    return "".join("\n\n" + (folder / f"{name}.md").read_text(encoding="utf-8").strip() for name in SKILLS.get(agent, []))


def system_prompt(spec: AgentSpec) -> str:
    from .datasheets import KIND_HELP

    role = spec.role.replace("KIND_HELP", KIND_HELP) + skill_text(spec.id)
    if spec.id.startswith("lead_"):
        role = f"{SOP}\n\n# Your role\n{role}"
    lines = "\n".join(f"- <{name}>: {meaning}" for name, meaning in spec.inputs.items())
    tools = "\n\n# Using tools\nBefore each tool call, write one short sentence saying what you are looking for and why." if spec.tools else ""
    return f"{role}{tools}\n\n# Your input\nEach request arrives in labelled sections. They mean:\n{lines}"


def render_input(spec: AgentSpec, values: dict[str, Any]) -> str:
    """Every section must be supplied, and nothing unexpected can be sent."""
    if set(values) != set(spec.inputs):
        raise ValueError(f"{spec.id}: expected {sorted(spec.inputs)}, got {sorted(values)}")
    parts = []
    for name in spec.inputs:
        value = values[name]
        text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, indent=1)
        parts.append(f"<{name}>\n{text or '(none)'}\n</{name}>")
    return "\n\n".join(parts)
